test("HTTP response outcomes have unique route-local identities", () => {
  const contract = queryContractSnapshot(), rule = contract.responseBodySchemas.query_contracts_success_v1.properties.http.items.properties.responseOutcomes.relationships.find((relationship) => relationship.kind === "unique_by"), valid = (values) => new Set(values.map((value) => value[rule.property])).size === values.length;
  assert.deepEqual(rule, { kind: "unique_by", property: "outcome" });
  for (const route of contract.http) assert.equal(valid(route.responseOutcomes), true, route.path);
  const route = contract.http.find((entry) => entry.responseOutcomes.length > 1);
  assert.equal(valid([...route.responseOutcomes, structuredClone(route.responseOutcomes[0])]), false);
});

test("seven token intelligence routes publish closed success envelopes", () => {
  const expected = new Map([["/internal/tokens/{mint}/market", "token_market_success_v1"], ["/internal/tokens/{mint}/security", "token_security_success_v1"], ["/internal/tokens/{mint}/holders", "token_holders_success_v1"], ["/api/v1/holders/{mint}", "token_holders_success_v1"], ["/internal/tokens/{mint}/trades", "token_trades_success_v1"], ["/internal/tokens/{mint}/ohlcv", "token_ohlcv_success_v1"], ["/internal/tokens/{mint}/liquidity", "token_liquidity_success_v1"]]), contract = queryContractSnapshot();
  for (const [pathname, schemaName] of expected) { const outcome = contract.http.find(({ path }) => path === pathname).responseOutcomes.find(({ status }) => status === 200), schema = contract.responseBodySchemas[schemaName]; assert.equal(outcome.representation.bodySchema, schemaName, pathname); assert.equal(schema.additionalProperties, false, pathname); assert.ok(schema.required.length >= 2, pathname); assert.deepEqual(schema.optional.filter((key) => schema.required.includes(key)), [], pathname); assert.ok([...schema.required, ...schema.optional].every((key) => schema.properties[key]), pathname); }
});

