  const quote = quoteRaydiumSnapshotExactInput({ snapshot, poolAddress: "pool", inputMint: "mint-0", amountIn: "1000", limitTick: -50, now }); assert.equal(quote.status, "quoted"); assert.deepEqual({ outputMint: quote.outputMint, zeroForOne: quote.zeroForOne, feeMode: quote.feeMode, feeRate: quote.feeRateMillionths, stateSlot: quote.stateSlot, mintEvidenceSlot: quote.mintEvidenceSlot, epoch: quote.epoch }, { outputMint: "mint-1", zeroForOne: true, feeMode: "from_input_static", feeRate: "3000", stateSlot: 100, mintEvidenceSlot: 103, epoch: 2 });
  assert.throws(() => quoteRaydiumSnapshotExactInput({ snapshot: { ...snapshot, observedAt: "2026-08-22T00:00:00Z" }, poolAddress: "pool", inputMint: "mint-0", amountIn: 1, limitTick: -10, now }), /evidence is invalid/);
  assert.throws(() => quoteRaydiumSnapshotExactInput({ snapshot: { ...snapshot, pools: [{ ...pool, status: "0" }] }, poolAddress: "pool", inputMint: "mint-0", amountIn: 1, limitTick: -10, now }), /status is malformed/);
  assert.throws(() => quoteRaydiumSnapshotExactInput({ snapshot: { ...snapshot, pools: [{ ...pool, mintEvidenceSlot: null }] }, poolAddress: "pool", inputMint: "mint-0", amountIn: 1, limitTick: -10, now }), /mint evidence is incomplete/);
