  const config = normalizeTransferFeeConfig({ withheldAmount: "7", olderTransferFee: { epoch: "10", transferFeeBasisPoints: 150, maximumFee: "10" }, newerTransferFee: { epoch: "12", transferFeeBasisPoints: 250, maximumFee: "20" } });
