  const block = parseBlock({ slot: 111, blockhash: "block-111", previousBlockhash: "block-110", parentSlot: 110, blockTime: 1_700_000_011, transactions: [entry], provenance: { source: "local-rpc", commitment: "finalized" } }); assert.equal(block.transfers.length, 1); assert.deepEqual({ mint: block.transfers[0].mint, amount: block.transfers[0].amountRaw, decimals: block.transfers[0].decimals, decoder: block.transfers[0].decoderVersion }, { mint: "canonical-mint", amount: "42", decimals: 6, decoder: 7 });
