  for (const invalidAddress of ["", "mint-a", "0OIl"]) { const invalid = { ...unsigned, completeMints: [invalidAddress] }; assert.throws(() => compileHolderExclusions({ ...invalid, contentSha256: holderExclusionContentSha256(invalid) }), /invalid complete holder exclusion mint/); }
  for (const entry of [{ ...unsigned.entries[0], mint: "mint-a" }, { ...unsigned.entries[0], tokenAccount: "vault-a" }, { ...unsigned.entries[1], owner: "burn-owner" }]) { const invalid = { ...unsigned, entries: [entry] }; assert.throws(() => compileHolderExclusions({ ...invalid, contentSha256: holderExclusionContentSha256(invalid) }), /invalid holder exclusion entry/); }
