test("PumpSwap fee tiers use exact market cap and canonical-pool selection", () => {
  assert.deepEqual(derivePumpPoolAuthority("7LSsEoJGhLeZzGvDofTdNg7M3JttxQqGWNLo6vWMpump"), { address: "9XDYTfQKwW8sHPqnFdUreMmtmffmkHVPGTNV2e3LKxNW", bump: 255 });
  assert.equal(pumpSwapPoolMarketCap({ baseMintSupplyRaw: "1000000000", baseReserveRaw: "250000000", quoteReserveRaw: "500000000" }), "2000000000");
  const feeConfig = { flatFees: { lpFeeBps: "20", protocolFeeBps: "5", creatorFeeBps: "0" }, feeTiers: [{ marketCapLamportsThresholdRaw: "0", fees: { lpFeeBps: "25", protocolFeeBps: "10", creatorFeeBps: "5" } }, { marketCapLamportsThresholdRaw: "1000000000", fees: { lpFeeBps: "20", protocolFeeBps: "8", creatorFeeBps: "4" } }, { marketCapLamportsThresholdRaw: "3000000000", fees: { lpFeeBps: "15", protocolFeeBps: "6", creatorFeeBps: "3" } }] };
  assert.deepEqual(selectPumpSwapFees({ feeConfig, canonicalPumpPool: true, baseMintSupplyRaw: "1000000000", baseReserveRaw: "250000000", quoteReserveRaw: "500000000" }), { source: "market_cap_tier", marketCapLamportsRaw: "2000000000", thresholdRaw: "1000000000", lpFeeBps: "20", protocolFeeBps: "8", creatorFeeBps: "4" }); assert.deepEqual(selectPumpSwapFees({ feeConfig, canonicalPumpPool: false, baseMintSupplyRaw: "1", baseReserveRaw: "1", quoteReserveRaw: "1" }), { source: "flat", marketCapLamportsRaw: null, lpFeeBps: "20", protocolFeeBps: "5", creatorFeeBps: "0" });
  assert.throws(() => pumpSwapPoolMarketCap({ baseMintSupplyRaw: "1", baseReserveRaw: "0", quoteReserveRaw: "1" }), /positive/); assert.throws(() => selectPumpSwapFees({ feeConfig: { ...feeConfig, feeTiers: [...feeConfig.feeTiers].reverse() }, canonicalPumpPool: true, baseMintSupplyRaw: "1", baseReserveRaw: "1", quoteReserveRaw: "1" }), /strictly ascending/); assert.throws(() => selectPumpSwapFees({ feeConfig: { ...feeConfig, flatFees: { lpFeeBps: "10000", protocolFeeBps: "0", creatorFeeBps: "0" } }, canonicalPumpPool: false, baseMintSupplyRaw: "1", baseReserveRaw: "1", quoteReserveRaw: "1" }), /invalid basis points/);
});

