test("Meteora quote schema binds aggregate fees and exact path to traversed bins", () => {
  const relation = queryContractSnapshot().responseBodySchemas.meteora_dlmm_quote_v1.relationships.find(({ kind }) => kind === "meteora_bin_traversal_economics"), quote = { swapForY: true, consumedInRaw: "1000", inputTransferFeeRaw: "10", grossOutputRaw: "1248", tradingFeeRaw: "2", protocolFeeRaw: "1", maximumFeeRateNumerator: "250000", startBinId: 1, endBinId: 0, binArrayIndexes: [0], binTraversal: [{ binId: 1, binArrayIndex: 0, consumedInRaw: "490", grossOutputRaw: "500", tradingFeeRaw: "1", protocolFeeRaw: "0", feeRateNumerator: "250000" }, { binId: 0, binArrayIndex: 0, consumedInRaw: "500", grossOutputRaw: "748", tradingFeeRaw: "1", protocolFeeRaw: "1", feeRateNumerator: "250000" }] };
  assert.equal(meteoraBinTraversalValid(quote, relation), true);
  for (const invalid of [{ ...quote, tradingFeeRaw: "3" }, { ...quote, protocolFeeRaw: "0" }, { ...quote, maximumFeeRateNumerator: "249999" }, { ...quote, endBinId: 1 }, { ...quote, binArrayIndexes: [1] }, { ...quote, binTraversal: quote.binTraversal.toReversed() }, { ...quote, binTraversal: [{ ...quote.binTraversal[0], binArrayIndex: 1 }, quote.binTraversal[1]] }]) assert.equal(meteoraBinTraversalValid(invalid, relation), false);
});

test("Meteora quote schema caps bin evidence to the decoder domain", () => {
  const schema = queryContractSnapshot().responseBodySchemas.meteora_dlmm_quote_v1;
  const indexes = schema.properties.binArrayIndexes.items;
  const traversal = schema.properties.binTraversal.items.properties;
  assert.deepEqual(indexes, { type: "integer", minimum: -6656, maximum: 6655 });
  assert.deepEqual(traversal.binArrayIndex, indexes);
  for (const property of [schema.properties.startBinId, schema.properties.endBinId, traversal.startBinId, traversal.endBinId]) {
    assert.equal(property.minimum, -465920);
    assert.equal(property.maximum, 465919);
  }
  assert.equal(Math.floor(-465920 / 70), indexes.minimum);
  assert.equal(Math.floor(465919 / 70), indexes.maximum);
  assert.equal(-6657 < indexes.minimum, true);
  assert.equal(6656 > indexes.maximum, true);
});

test("Meteora quote schema rejects per-array input and output redistribution", () => {
  const schema = queryContractSnapshot().responseBodySchemas.meteora_dlmm_quote_v1;
  const relation = schema.relationships.find(({ kind }) => kind === "meteora_bin_array_output_capacity");
  const dimensions = [[relation.input, relation.inputCapacity], [relation.output, relation.outputCapacity], [relation.tradingFee, relation.tradingFeeCapacity], [relation.protocolFee, relation.protocolFeeCapacity]];
  const valid = (rows) => rows.every((row, index) => dimensions.every(([value, capacity]) => index === rows.length - 1 ? BigInt(row[value]) <= BigInt(row[capacity]) : BigInt(row[value]) === BigInt(row[capacity])) && BigInt(row[relation.maximumFeeRate]) === BigInt(row[relation.maximumFeeRateCapacity]));
  const real = [{ consumedInRaw: "101", inputCapacityRaw: "101", grossOutputRaw: "100", outputCapacityRaw: "100", tradingFeeRaw: "1", tradingFeeCapacityRaw: "1", protocolFeeRaw: "0", protocolFeeCapacityRaw: "0", maximumFeeRateNumerator: "25000", maximumFeeRateCapacityNumerator: "25000" }, { consumedInRaw: "99", inputCapacityRaw: "101", grossOutputRaw: "98", outputCapacityRaw: "100", tradingFeeRaw: "1", tradingFeeCapacityRaw: "1", protocolFeeRaw: "0", protocolFeeCapacityRaw: "0", maximumFeeRateNumerator: "25000", maximumFeeRateCapacityNumerator: "25000" }];
  assert.deepEqual(relation, { kind: "meteora_bin_array_output_capacity", traversal: "binTraversal", input: "consumedInRaw", inputCapacity: "inputCapacityRaw", output: "grossOutputRaw", outputCapacity: "outputCapacityRaw", tradingFee: "tradingFeeRaw", tradingFeeCapacity: "tradingFeeCapacityRaw", protocolFee: "protocolFeeRaw", protocolFeeCapacity: "protocolFeeCapacityRaw", maximumFeeRate: "maximumFeeRateNumerator", maximumFeeRateCapacity: "maximumFeeRateCapacityNumerator" });
  assert.equal(valid(real), true);
  assert.equal(valid([{ ...real[0], grossOutputRaw: "101" }, { ...real[1], grossOutputRaw: "97" }]), false);
  assert.equal(valid([{ ...real[0], grossOutputRaw: "99" }, { ...real[1], grossOutputRaw: "99" }]), false);
  assert.equal(valid([{ ...real[0], consumedInRaw: "102" }, { ...real[1], consumedInRaw: "98" }]), false);
  assert.equal(valid([{ ...real[0], tradingFeeRaw: "2" }, { ...real[1], tradingFeeRaw: "0" }]), false);
  assert.equal(valid([{ ...real[0], protocolFeeRaw: "1" }, real[1]]), false);
  assert.equal(valid([real[0], { ...real[1], maximumFeeRateNumerator: "24999" }]), false);
});

