test("raw inbox retention is dry-run-first and deletes only unchanged durable files", async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-inbox-retention-")), inbox = path.join(root, "inbox"), dataFile = path.join(root, "index.json"), manifestFile = path.join(root, "manifest.json"), archiveReceiptFile = path.join(root, "receipt.json"); await fs.mkdir(inbox); const old = path.join(inbox, "old.json"), changed = path.join(inbox, "changed.json"), pending = path.join(inbox, "pending.json"); await fs.writeFile(old, "durable"); await fs.writeFile(changed, "changed-now"); await fs.writeFile(pending, "pending"); const hash = (value) => crypto.createHash("sha256").update(value).digest("hex");
  const recoveryState = { processedFiles: { "old.json": { fingerprint: hash("durable"), parserVersion: 2 }, "changed.json": { fingerprint: hash("changed-before"), parserVersion: 2 } }, checkpoints: {}, deadLetters: [], reorgCorrections: [] }; await fs.writeFile(dataFile, JSON.stringify(recoveryState)); const past = new Date("2020-01-01T00:00:00Z"); await Promise.all([fs.utimes(old, past, past), fs.utimes(changed, past, past), fs.utimes(pending, past, past)]);
  const blocked = await retainInbox({ inbox, dataFile, archiveReceiptFile, retentionSeconds: 3600, now: Date.parse("2020-01-02T00:00:00Z"), confirmDelete: true }); assert.deepEqual(blocked.deleted, []); assert.equal(blocked.retained.unarchived, 1); assert.equal(blocked.archiveReceiptValid, false);
  await createInboxManifest({ inbox, output: manifestFile, archiveId: "20200101T000000Z" }); await completeArchiveReceipt({ manifestFile, output: archiveReceiptFile, completedAt: "2020-01-01T01:00:00.000Z" });
  const malformedReceipt = JSON.parse(await fs.readFile(archiveReceiptFile, "utf8")); malformedReceipt.completedAt = "2020-01-01T01:00:00Z"; await fs.writeFile(archiveReceiptFile, JSON.stringify(malformedReceipt)); assert.equal((await retainInbox({ inbox, dataFile, archiveReceiptFile, retentionSeconds: 3600, now: Date.parse("2020-01-02T00:00:00Z") })).archiveReceiptValid, false); await completeArchiveReceipt({ manifestFile, output: archiveReceiptFile, completedAt: "2020-01-01T01:00:00.000Z" });
  await fs.writeFile(dataFile, JSON.stringify({ ...recoveryState, checkpoints: { inbox: { filename: "old.json", fingerprint: hash("detached"), parserVersion: 2, updatedAt: "2020-01-01T00:00:00.000Z" } } })); await assert.rejects(retainInbox({ inbox, dataFile, archiveReceiptFile, retentionSeconds: 3600, now: Date.parse("2020-01-02T00:00:00Z"), confirmDelete: true }), /recovery evidence invalid/); assert.doesNotReject(fs.access(old)); await fs.writeFile(dataFile, JSON.stringify(recoveryState));
  await fs.writeFile(dataFile, JSON.stringify({ ...recoveryState, checkpoints: { deadLetterOverflow: { schemaVersion: 1, droppedCount: 1, firstObservedAt: "2020-01-01T00:00:00.000Z", lastObservedAt: "2020-01-01T00:00:00.000Z" } } })); await assert.rejects(retainInbox({ inbox, dataFile, archiveReceiptFile, retentionSeconds: 3600, now: Date.parse("2020-01-02T00:00:00Z"), confirmDelete: true }), /dead-letter capacity exceeded/); assert.doesNotReject(fs.access(old)); await fs.writeFile(dataFile, JSON.stringify(recoveryState));
  const preview = await retainInbox({ inbox, dataFile, archiveReceiptFile, retentionSeconds: 3600, now: Date.parse("2020-01-02T00:00:00Z") }); assert.deepEqual(preview.eligible, ["old.json"]); assert.equal(preview.deleted.length, 0); assert.equal(preview.retained.changed, 1); assert.equal(preview.retained.uncheckpointed, 1); const applied = await retainInbox({ inbox, dataFile, archiveReceiptFile, retentionSeconds: 3600, now: Date.parse("2020-01-02T00:00:00Z"), confirmDelete: true }); assert.deepEqual(applied.deleted, ["old.json"]); await assert.rejects(fs.access(old)); assert.doesNotReject(fs.access(changed));
  await assert.rejects(retainInbox({ inbox, dataFile, archiveReceiptFile, retentionSeconds: 3600, now: Date.parse("2020-01-02T00:00:00Z"), maximumStateBytes: 8 }), /recovery evidence invalid/); const boundedReceipt = await retainInbox({ inbox, dataFile, archiveReceiptFile, retentionSeconds: 3600, now: Date.parse("2020-01-02T00:00:00Z"), maximumReceiptBytes: 8 }); assert.equal(boundedReceipt.archiveReceiptValid, false); await assert.rejects(retainInbox({ inbox, dataFile, archiveReceiptFile, retentionSeconds: 0 }), /invalid inbox retention parameters/);
});

