test("provider Retry-After hints are bounded and never reopen immediately", () => {
  const now = Date.parse("2026-08-22T00:00:00Z");
  assert.equal(parseRetryAfterMs("0", now), MIN_RETRY_AFTER_MS);
  assert.equal(parseRetryAfterMs("Sat, 21 Aug 2026 23:59:00 GMT", now), MIN_RETRY_AFTER_MS);
  assert.equal(parseRetryAfterMs("999999999999999999999", now), MAX_RETRY_AFTER_MS);
  assert.equal(parseRetryAfterMs("3601", now), MAX_RETRY_AFTER_MS);
  assert.equal(parseRetryAfterMs("00001", now), MIN_RETRY_AFTER_MS);
  assert.equal(parseRetryAfterMs("00002", now), 2_000);
  assert.equal(parseRetryAfterMs("00003601", now), MAX_RETRY_AFTER_MS);
  assert.equal(parseRetryAfterMs("2", now), 2_000);
  assert.equal(parseRetryAfterMs("invalid", now), null);
});

test("local validator client correlates concurrent JSON-RPC responses", async () => {
  const fetchImpl = async (_endpoint, options) => { const request = JSON.parse(options.body); await new Promise((resolve) => setTimeout(resolve, request.method === "slow" ? 5 : 0)); return { ok: true, json: async () => ({ jsonrpc: "2.0", id: request.id, result: request.method === "getGenesisHash" ? MAINNET_GENESIS_HASH : request.method }) }; };
  const client = new LocalValidatorClient("http://127.0.0.1:8899", { fetchImpl, timeoutMs: 1_000 }); await assert.rejects(() => client.call("getSlot"), /requires genesis verification/); await client.assertGenesis(); assert.deepEqual(await Promise.all([client.call("slow"), client.call("fast")]), ["slow", "fast"]);
  const mismatched = new LocalValidatorClient("http://127.0.0.1:8899", { fetchImpl: async (_endpoint, options) => { const request = JSON.parse(options.body); return { ok: true, json: async () => request.method === "getGenesisHash" ? ({ jsonrpc: "2.0", id: request.id, result: MAINNET_GENESIS_HASH }) : ({ jsonrpc: "2.0", id: request.id + 1, result: "stale" }) }; } });
  await mismatched.assertGenesis(); await assert.rejects(() => mismatched.call("getSlot"), /invalid JSON-RPC response envelope/);
  const ambiguous = new LocalValidatorClient("http://127.0.0.1:8899", { fetchImpl: async (_endpoint, options) => { const request = JSON.parse(options.body); return { ok: true, json: async () => request.method === "getGenesisHash" ? ({ jsonrpc: "2.0", id: request.id, result: MAINNET_GENESIS_HASH }) : ({ jsonrpc: "2.0", id: request.id, result: null, error: null }) }; } });
  await ambiguous.assertGenesis(); await assert.rejects(() => ambiguous.call("getHealth"), /invalid JSON-RPC response envelope/);
});

test("RPC response decoding rejects oversized and malformed bodies before parsing", async () => {
  await assert.rejects(() => readBoundedRpcJson(new Response("x".repeat(1_025)), 1_024), /exceeds byte limit/);
  await assert.rejects(() => readBoundedRpcJson(new Response("not-json"), 1_024), /JSON is invalid/);
  await assert.rejects(() => readBoundedRpcJson(new Response(Buffer.from([0x7b, 0x22, 0x76, 0x22, 0x3a, 0x22, 0xc3, 0x28, 0x22, 0x7d])), 1_024), /JSON is invalid/);
  let parsed = false; const fetchImpl = async (_endpoint, options) => { const request = JSON.parse(options.body); if (request.method === "getGenesisHash") return { ok: true, json: async () => ({ jsonrpc: "2.0", id: request.id, result: MAINNET_GENESIS_HASH }) }; return { ok: true, headers: { get: (name) => name === "content-length" ? "1025" : null }, json: async () => { parsed = true; return {}; } }; };
  const client = new LocalValidatorClient("http://127.0.0.1:8899", { fetchImpl, maxResponseBytes: 1_024 }); await client.assertGenesis(); await assert.rejects(() => client.call("getBlock"), /exceeds byte limit/); assert.equal(parsed, false);
  assert.throws(() => new LocalValidatorClient(undefined, { maxResponseBytes: 1_023 }), /response limit/); assert.throws(() => new ExternalRpcPool([{ name: "solana-public", endpoint: "https://api.mainnet.solana.com" }], { maxResponseBytes: 268_435_457 }), /response limit/);
});

