  await fs.unlink(publicIndexFile); await fs.mkdir(publicIndexFile); const schema = queryContractSnapshot().responseBodySchemas.static_asset_unavailable_v1, allowed = [...schema.required, ...schema.optional]; for (const pathname of ["/", "/index.html"]) { const unavailable = await fetch(`${base}${pathname}`), body = await unavailable.json(); assert.equal(unavailable.status, 503); assert.deepEqual(body, { error: "static_asset_unavailable" }); assert.ok(schema.required.every((key) => key in body)); assert.ok(Object.keys(body).every((key) => allowed.includes(key))); assert.ok(schema.properties.error.values.includes(body.error)); } const metrics = await (await fetch(`${base}/metrics`)).text(); assert.match(metrics, /terminal_dex_internal_failures_total\{operation="http_internal_error"\} 2/);
