test("decodes pinned Switchboard V2 aggregator evidence for OpenBook policy", () => {
  const data = Buffer.alloc(3_851), address = "switchboard-feed"; Buffer.from([217, 230, 65, 101, 201, 162, 27, 125]).copy(data); data.writeUInt32LE(3, 236); data.writeUInt32LE(3, 341); data.writeBigUInt64LE(800n, 350); data.writeBigInt64LE(2_345n, 366); data.writeUInt32LE(2, 382); data.writeBigInt64LE(12n, 386); data.writeUInt32LE(2, 402); const evidence = decodeOpenBookOracleAccount(address, { owner: "switchboard-owner", data: [data.toString("base64"), "base64"] });
  assert.deepEqual({ provider: evidence.provider, mode: evidence.resolutionMode, minimum: evidence.minimumOracleResults, successful: evidence.successfulResults, result: evidence.resultMantissaRaw, scale: evidence.resultScale, deviation: evidence.standardDeviationMantissaRaw, slot: evidence.lastUpdateSlotRaw }, { provider: "switchboard_v2", mode: "round", minimum: 3, successful: 3, result: "2345", scale: 2, deviation: "12", slot: "800" });
  assert.equal(validOpenBookOracleEvidence(evidence, address), true); assert.equal(validOpenBookOracleEvidence({ ...evidence, successfulResults: 2 }, address), false);
  const filter = Buffer.alloc(8); filter.writeDoubleLE(0.1); const market = { oracleB: null, oracleEvidenceA: evidence, oracleEvidenceB: null, oracleConfidenceFilterBitsRaw: filter.readBigUInt64LE().toString(), oracleMaxStalenessSlots: "50", mintDecimals0: 6, mintDecimals1: 6, baseLotSizeRaw: "1000", quoteLotSizeRaw: "100" };
  assert.deepEqual(evaluateOpenBookOraclePolicy(market, 820), { valid: true, reason: null, oraclePriceLots: "234", providers: ["switchboard_v2"], source: "oracle_a" }); const insufficient = Buffer.from(data); insufficient.writeUInt32LE(2, 341); assert.throws(() => decodeOpenBookOracleAccount(address, { owner: "switchboard-owner", data: [insufficient.toString("base64"), "base64"] }), /invalid aggregator state/); insufficient[3_712] = 1; assert.equal(decodeOpenBookOracleAccount(address, { owner: "switchboard-owner", data: [insufficient.toString("base64"), "base64"] }).resolutionMode, "sliding");
});

