test("decodes Raydium AMM v4 swaps from exact instruction-bound ray_log evidence", () => {
  const encode58 = (bytes) => { const alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"; let value = 0n, output = ""; for (const byte of bytes) value = value * 256n + BigInt(byte); while (value) { output = alphabet[Number(value % 58n)] + output; value /= 58n; } for (const byte of bytes) { if (byte) break; output = `1${output}`; } return output || "1"; };
  const program = "675kPX9MHTjS2zt1qfr1NYHuzeLXfQM9H24wFSUt1Mp8", accounts = Array.from({ length: 17 }, (_, index) => `amm-v4-${index}`); accounts[0] = SPL_TOKEN_PROGRAM;
  const instructionData = Buffer.alloc(17); instructionData[0] = 9; instructionData.writeBigUInt64LE(100n, 1); instructionData.writeBigUInt64LE(180n, 9);
  const log = Buffer.alloc(57); log[0] = 3; log.writeBigUInt64LE(100n, 1); log.writeBigUInt64LE(180n, 9); log.writeBigUInt64LE(1n, 17); log.writeBigUInt64LE(1_000n, 25); log.writeBigUInt64LE(5_000n, 33); log.writeBigUInt64LE(10_000n, 41); log.writeBigUInt64LE(190n, 49);
  const balance = (accountIndex, mint, amount) => ({ accountIndex, mint, owner: "owner", programId: SPL_TOKEN_PROGRAM, uiTokenAmount: { amount, decimals: 6 } });
  const entry = { transaction: { message: { accountKeys: accounts, instructions: [{ programId: program, accounts: accounts.map((_, index) => index), data: encode58(instructionData) }] } }, meta: { err: null, preTokenBalances: [balance(4, "coin-mint", "5000"), balance(5, "pc-mint", "10000"), balance(14, "pc-mint", "1000"), balance(15, "coin-mint", "0")], postTokenBalances: [balance(4, "coin-mint", "4810"), balance(5, "pc-mint", "10100"), balance(14, "pc-mint", "900"), balance(15, "coin-mint", "190")], logMessages: [`Program ${program} invoke [1]`, `Program log: ray_log: ${log.toString("base64")}`, `Program ${program} success`] } };
  const [event] = decodeRaydiumAmmV4SwapEvents(entry, "amm-v4-signature");
  assert.deepEqual({ protocol: event.protocol, pool: event.pool, user: event.user, inputMint: event.inputMint, outputMint: event.outputMint, inputAmountRaw: event.inputAmountRaw, outputAmountRaw: event.outputAmountRaw, inputVaultBeforeRaw: event.inputVaultBeforeRaw, outputVaultBeforeRaw: event.outputVaultBeforeRaw, tradeFeeRaw: event.tradeFeeRaw, feeEvidence: event.feeEvidence }, { protocol: "raydium-amm-v4", pool: accounts[1], user: accounts[16], inputMint: "pc-mint", outputMint: "coin-mint", inputAmountRaw: "100", outputAmountRaw: "190", inputVaultBeforeRaw: "10000", outputVaultBeforeRaw: "5000", tradeFeeRaw: null, feeEvidence: "unavailable_in_program_log" });
  const parsed = parseBlock({ slot: 901, blockhash: "amm-v4-block", previousBlockhash: "amm-v4-parent", parentSlot: 900, blockTime: 1_700_000_000, transactions: [{ ...entry, transaction: { ...entry.transaction, signatures: ["amm-v4-signature"] }, meta: { ...entry.meta, fee: 5_000 } }], provenance: { commitment: "finalized" } }); assert.deepEqual({ count: parsed.swaps.length, registryVersion: parsed.swaps[0].registryVersion, tradeFeeRaw: parsed.swaps[0].tradeFeeRaw, feeEvidence: parsed.swaps[0].feeEvidence }, { count: 1, registryVersion: 20, tradeFeeRaw: null, feeEvidence: "unavailable_in_program_log" });
  const wrongBound = structuredClone(entry); const wrongLog = Buffer.from(log); wrongLog.writeBigUInt64LE(101n, 1); wrongBound.meta.logMessages[1] = `Program log: ray_log: ${wrongLog.toString("base64")}`; assert.deepEqual(decodeRaydiumAmmV4SwapEvents(wrongBound, "bad"), []);
  const foreignProgram = structuredClone(entry); foreignProgram.transaction.message.accountKeys[0] = "foreign-token-program"; assert.deepEqual(decodeRaydiumAmmV4SwapEvents(foreignProgram, "bad"), []);
  const malformedLog = structuredClone(entry); malformedLog.meta.logMessages[1] = "Program log: ray_log: invalid!"; assert.deepEqual(decodeRaydiumAmmV4SwapEvents(malformedLog, "bad"), []);
});

test("decodes and persists exact Raydium AMM v4 Initialize2 lifecycle", async () => {
  const encode58 = (bytes) => { const alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"; let value = 0n, output = ""; for (const byte of bytes) value = value * 256n + BigInt(byte); while (value) { output = alphabet[Number(value % 58n)] + output; value /= 58n; } for (const byte of bytes) { if (byte) break; output = `1${output}`; } return output || "1"; };
  const programId = "675kPX9MHTjS2zt1qfr1NYHuzeLXfQM9H24wFSUt1Mp8", accounts = Array.from({ length: 21 }, (_, index) => `amm-v4-create-${index}`), data = Buffer.alloc(26); accounts[0] = SPL_TOKEN_PROGRAM; accounts[1] = "ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL"; accounts[2] = "11111111111111111111111111111111"; accounts[3] = "SysvarRent111111111111111111111111111111111"; data[0] = 1; data[1] = 254; data.writeBigUInt64LE(30n, 2); data.writeBigUInt64LE(20n, 10); data.writeBigUInt64LE(10n, 18);
  const instruction = { programId, accounts, data: encode58(data) }, entry = { transaction: { signatures: ["amm-v4-create"], message: { accountKeys: [], instructions: [instruction] } }, meta: { err: null, fee: 1, logMessages: [], preTokenBalances: [], postTokenBalances: [] } };
  assert.deepEqual(recognizedLifecycleInstructionOutput(instruction), { protocol: "raydium-amm-v4", type: "pool_created" });
  const [decoded] = decodeRaydiumAmmV4PoolInitializations(entry, "amm-v4-create"); assert.deepEqual({ pool: decoded.pool, creator: decoded.creator, mint0: decoded.tokenMint0, mint1: decoded.tokenMint1, amount0: decoded.initialAmount0Raw, amount1: decoded.initialAmount1Raw, openTime: decoded.requestedOpenTime, nonce: decoded.nonce }, { pool: accounts[4], creator: accounts[17], mint0: accounts[8], mint1: accounts[9], amount0: "10", amount1: "20", openTime: "30", nonce: 254 });
  const block = parseBlock({ slot: 904, blockhash: "amm-v4-create-block", previousBlockhash: "amm-v4-create-parent", parentSlot: 903, blockTime: 1_700_000_004, transactions: [entry], provenance: { commitment: "finalized" } }), store = new IndexStore("unused"); assert.equal(block.poolLifecycleEvents[0].registryVersion, 20); assert.equal(block.poolLifecycleEvents[0].decoderVersion, 2); assert.equal(canonicalLifecycleTransition(block.poolLifecycleEvents[0]), true); await store.load(); store.apply(block); assert.equal(store.pool(accounts[4]).summary.lifecycle.initialAmount0Raw, "10"); assert.equal(store.decoderOutputCoverageQuality().complete, true);
  for (const mutate of [(row) => { row.data = encode58(data.subarray(0, 25)); }, (row) => { const zero = Buffer.from(data); zero.writeBigUInt64LE(0n, 18); row.data = encode58(zero); }, (row) => { row.accounts[0] = "foreign-token-program"; }, (row) => { row.accounts[9] = row.accounts[8]; }]) { const invalid = structuredClone(instruction); mutate(invalid); assert.deepEqual(decodeRaydiumAmmV4PoolInitializations({ ...entry, transaction: { ...entry.transaction, message: { ...entry.transaction.message, instructions: [invalid] } } }, "invalid"), []); }
  assert.deepEqual(decodeRaydiumAmmV4PoolInitializations({ ...entry, meta: { ...entry.meta, err: { InstructionError: [0, "failed"] } } }, "failed"), []);
});

test("decodes and persists successful Raydium CPMM pool initialization lifecycle", async () => {
  const encode58 = (bytes) => { const alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"; let value = 0n; for (const byte of bytes) value = value * 256n + BigInt(byte); let output = ""; while (value) { output = alphabet[Number(value % 58n)] + output; value /= 58n; } for (const byte of bytes) { if (byte) break; output = `1${output}`; } return output || "1"; };
  const programId = "CPMMoo8L3F4NbTegBCKVNunggL7H1ZpdTHKxQB5qKP1C", accounts = Array.from({ length: 20 }, (_, index) => `account-${index}`), data = Buffer.alloc(32); crypto.createHash("sha256").update("global:initialize").digest().copy(data, 0, 0, 8); data.writeBigUInt64LE(10n, 8); data.writeBigUInt64LE(20n, 16); data.writeBigUInt64LE(30n, 24);
  const entry = { transaction: { signatures: ["create-pool-signature"], message: { accountKeys: ["payer"], instructions: [{ programId, accounts, data: encode58(data) }] } }, meta: { err: null, fee: 1, logMessages: [], preTokenBalances: [], postTokenBalances: [] } };
  const decoded = decodeRaydiumCpmmPoolInitializations(entry, "create-pool-signature"); assert.deepEqual({ pool: decoded[0].pool, tokenMint0: decoded[0].tokenMint0, tokenMint1: decoded[0].tokenMint1, initialAmount0Raw: decoded[0].initialAmount0Raw, initialAmount1Raw: decoded[0].initialAmount1Raw, requestedOpenTime: decoded[0].requestedOpenTime }, { pool: "account-3", tokenMint0: "account-4", tokenMint1: "account-5", initialAmount0Raw: "10", initialAmount1Raw: "20", requestedOpenTime: "30" });
  const block = parseBlock({ slot: 900, blockhash: "block-900", previousBlockhash: "block-899", parentSlot: 899, blockTime: 1_700_000_000, transactions: [entry], provenance: { commitment: "finalized" } }); assert.equal(block.poolLifecycleEvents.length, 1); const store = new IndexStore("unused"); await store.load(); store.apply(block); assert.equal(store.pool("account-3").summary.lifecycle.initialAmount1Raw, "20"); store.rebuildAggregates(); assert.equal(store.pool("account-3").summary.pairIdentitySource, "protocol_instruction");
  assert.deepEqual(decodeRaydiumCpmmPoolInitializations({ ...entry, meta: { ...entry.meta, err: { InstructionError: [0, "failed"] } } }, "failed"), []); const malformed = structuredClone(entry); malformed.transaction.message.instructions[0].data = "0OIl"; assert.deepEqual(decodeRaydiumCpmmPoolInitializations(malformed, "bad"), []);
});

