  const instruction = (side) => { const data = Buffer.alloc(side === "sell" ? 24 : 25); Buffer.from(side === "sell" ? [51, 230, 133, 164, 1, 127, 131, 173] : [198, 46, 21, 82, 180, 217, 232, 112]).copy(data); data.writeBigUInt64LE(100n, 8); data.writeBigUInt64LE(90n, 16); if (side === "buy") data[24] = 1; return { programId: program, accounts: accounts(side), data: encode58(data) }; };
