test("operational endpoints fail closed without throwing on malformed persisted collection shapes", async (t) => {
  const store = new IndexStore("unused"); await store.load(); const block = parseBlock(JSON.parse(await fs.readFile(fixture, "utf8"))); store.apply(block); store.state.deadLetters = {}; store.state.events = {}; const now = block.blockTime * 1_000; assert.deepEqual({ status: store.health(120_000, now).status, reason: store.health(120_000, now).reason }, { status: "invalid_evidence", reason: "indexed_state_structure_invalid" }); assert.equal(store.stats().deadLetters, null); assert.equal(store.stats().unresolvedDeadLetters, null); assert.equal(store.dataCapabilities(120_000, now).canonicalRecoveryState, false); assert.equal(store.botReadiness(120_000, now, "pool-address").reason, "index_unhealthy");
  const server = createServer({ staleAfterMs: 120_000, webSocketHeartbeatMs: 60_000 }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const base = `http://127.0.0.1:${server.address().port}`; for (const pathname of ["/api/stats", "/internal/feed/health"]) { const response = await fetch(`${base}${pathname}`); assert.equal(response.status, 503); assert.equal((await response.json()).structure.canonical, false); } const metrics = await fetch(`${base}/metrics`); assert.equal(metrics.status, 200); assert.match(await metrics.text(), /terminal_dex_index_healthy 0/); const rpc = await fetch(`${base}/rpc`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "getIndexerStats" }) }); assert.equal(rpc.status, 200); const rpcBody = await rpc.json(); assert.equal(rpcBody.result.structure.canonical, false); assert.equal(rpcBody.result.deadLetters, null);
});

test("restart quarantines malformed persisted state without overwriting source evidence", async (t) => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-state-quarantine-")), filename = path.join(root, "index.json"), seed = new IndexStore(filename); await seed.load(); seed.apply(parseBlock(JSON.parse(await fs.readFile(fixture, "utf8")))); await seed.save();
  const malformed = JSON.parse(await fs.readFile(filename, "utf8")); malformed.deadLetters = null; malformed.events = {}; const original = `${JSON.stringify(malformed)}\n`; await fs.writeFile(filename, original);
  const store = new IndexStore(filename); await store.load(); assert.equal(store.loaded, true); assert.deepEqual(store.structureQuality(), { canonical: false, reason: "indexed_state_structure_invalid", fields: ["deadLetters", "events"] }); assert.equal(store.health().reason, "indexed_state_structure_invalid"); assert.equal(store.hasFile("anything", "anything"), false); assert.throws(() => store.apply({}), /index state is quarantined/); await assert.rejects(store.save(), /index state is quarantined/); assert.equal(await fs.readFile(filename, "utf8"), original);
  const server = createServer({ staleAfterMs: 120_000 }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const base = `http://127.0.0.1:${server.address().port}`, response = await fetch(`${base}/api/stats`); assert.equal(response.status, 503); const body = await response.json(); assert.equal(body.structure.reason, "indexed_state_structure_invalid"); assert.deepEqual(body.structure.fields, ["deadLetters", "events"]); const metrics = await (await fetch(`${base}/metrics`)).text(); assert.match(metrics, /terminal_dex_index_state_quarantined 1/); assert.match(metrics, /terminal_dex_index_state_invalid_fields 2/); assert.match(metrics, /terminal_dex_dead_letter_retries_by_stage\{stage="input_parse"\} NaN/);
  for (const pathname of ["/internal/trending", "/api/v1/risk/pool-address"]) { const rejected = await fetch(`${base}${pathname}`); assert.equal(rejected.status, 503); assert.deepEqual(await rejected.json(), { schemaVersion: 1, available: false, reason: "indexed_state_structure_invalid" }); }
  const gaps = await fetch(`${base}/internal/feed/gaps`); assert.equal(gaps.status, 503); assert.deepEqual(await gaps.json(), { schemaVersion: 1, available: false, reason: "indexed_state_structure_invalid", fields: ["deadLetters", "events"] });
  const prepare = await fetch(`${base}/internal/pools/pool-address/prepare-swap`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ amountRaw: "1", inputMint: "mint" }) }); assert.equal(prepare.status, 503); assert.equal((await prepare.json()).reason, "indexed_state_structure_invalid");
  const rpc = await fetch(`${base}/rpc`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify([{ jsonrpc: "2.0", id: 1, method: "getIndexerHealth" }, { jsonrpc: "2.0", id: 2, method: "getIndexedBlock", params: { slot: 1 } }]) }), rpcBody = await rpc.json(); assert.equal(rpc.status, 200); assert.equal(rpcBody[0].result.reason, "indexed_state_structure_invalid"); assert.deepEqual(rpcBody[1].error, { code: -32000, message: "Index state unavailable" });
  const socket = new WebSocket(`ws://127.0.0.1:${server.address().port}/ws`); let rejected = false; await new Promise((resolve) => { socket.onerror = () => { rejected = true; resolve(); }; }); assert.equal(rejected, true);
});

test("restart quarantines invalid JSON without disclosing or replacing its contents", async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-json-quarantine-")), filename = path.join(root, "index.json"), inbox = path.join(root, "inbox"), original = '{"privateProviderToken":"do-not-log"'; await fs.writeFile(filename, original); await fs.mkdir(inbox); await fs.writeFile(path.join(inbox, "1.json"), "{}"); const store = new IndexStore(filename); await store.load();
  assert.deepEqual(store.structureQuality(), { canonical: false, reason: "indexed_state_json_invalid", fields: [] }); assert.equal(store.health().reason, "indexed_state_json_invalid"); assert.throws(() => store.recordDeadLetter("input", "hash", "failure"), /index state is quarantined/); await assert.rejects(store.save(), /index state is quarantined/); assert.equal(await fs.readFile(filename, "utf8"), original); assert.doesNotMatch(JSON.stringify(store.loadFailure), /privateProviderToken|do-not-log/);
  await assert.rejects(indexInbox({ inbox }, store), (error) => error.code === "INDEX_STATE_QUARANTINED" && error.reason === "indexed_state_json_invalid"); await assert.rejects(applySnapshotArtifacts({}, store), (error) => error.code === "INDEX_STATE_QUARANTINED"); assert.equal(await fs.readFile(filename, "utf8"), original);
  assert.throws(() => assertWarehousePublicationState(store), (error) => error.code === "INDEX_STATE_QUARANTINED" && error.reason === "indexed_state_json_invalid"); await assert.rejects(reconcileDeadLetters({ dataFile: filename }), (error) => error.code === "INDEX_STATE_QUARANTINED");
  for (const policy of [{ artifactOnly: false, requested: ["pool"] }, { artifactOnly: false, requested: [] }, { artifactOnly: true, requested: [] }]) assert.throws(() => assertSnapshotAcquisitionAllowed(store, policy), (error) => error.code === "INDEX_STATE_QUARANTINED"); assert.deepEqual(assertSnapshotAcquisitionAllowed(store, { artifactOnly: true, requested: ["pool"] }), { artifactOnly: true, discovery: false, localMutation: false });
  let cycles = 0; const result = await new Promise((resolve) => { watchInbox({ inbox, pollMs: 5 }, store, (value) => { cycles++; resolve(value); }); }); assert.deepEqual({ suspended: result.suspended, reason: result.reason, code: result.errors[0].code }, { suspended: true, reason: "indexed_state_json_invalid", code: "INDEX_STATE_QUARANTINED" }); await new Promise((resolve) => setTimeout(resolve, 20)); assert.equal(cycles, 1);
});

test("restart quarantines unsafe or oversized state files before parsing", async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-state-file-boundary-")), filename = path.join(root, "index.json"), original = " {}\n"; await fs.writeFile(filename, original); const store = new IndexStore(filename, 1_000, null, null, null, 200, 2); await store.load(); assert.deepEqual(store.structureQuality(), { canonical: false, reason: "indexed_state_file_invalid", fields: [] }); assert.throws(() => store.assertWritable(), (error) => error.code === "INDEX_STATE_QUARANTINED" && error.reason === "indexed_state_file_invalid"); await assert.rejects(store.save(), /index state is quarantined/); assert.equal(await fs.readFile(filename, "utf8"), original); assert.throws(() => new IndexStore(filename, 1_000, null, null, null, 200, 0), /maximum index state size/);
  const malformedFile = path.join(root, "malformed.json"), malformed = Buffer.from([0x7b, 0x22, 0x62, 0x6c, 0x6f, 0x63, 0x6b, 0x73, 0x22, 0x3a, 0x7b, 0x22, 0xc3, 0x28, 0x22, 0x3a, 0x7b, 0x7d, 0x7d, 0x7d]); await fs.writeFile(malformedFile, malformed); const malformedStore = new IndexStore(malformedFile); await malformedStore.load(); assert.deepEqual(malformedStore.structureQuality(), { canonical: false, reason: "indexed_state_json_invalid", fields: [] }); assert.equal(Buffer.compare(await fs.readFile(malformedFile), malformed), 0);
});

test("JSON-RPC rejects oversized bodies with a stable 413 contract", async (t) => {
  const store = new IndexStore("unused"); await store.load(); const server = createServer({ rpcMaxBodyBytes: 128 }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const response = await fetch(`http://127.0.0.1:${server.address().port}/rpc`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "getIndexerHealth", padding: "x".repeat(256) }) }); assert.equal(response.status, 413); assert.deepEqual(await response.json(), { error: "payload_too_large", detail: "request body exceeds 128 bytes" });
});

test("JSON POST routes reject ambiguous media types and content encodings", async (t) => {
  const store = new IndexStore("unused"); await store.load(); const server = createServer({}, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const endpoint = `http://127.0.0.1:${server.address().port}/rpc`, body = JSON.stringify({ jsonrpc: "2.0", id: 1, method: "getIndexerStats" });
  for (const headers of [{ "content-type": "text/plain" }, { "content-type": "application/json", "content-encoding": "gzip" }]) { const response = await fetch(endpoint, { method: "POST", headers, body }); assert.equal(response.status, 415); assert.equal((await response.json()).error, "unsupported_media_type"); }
  const accepted = await fetch(endpoint, { method: "POST", headers: { "content-type": "application/json; charset=UTF-8" }, body }); assert.equal(accepted.status, 200); assert.equal((await accepted.json()).result.structure.canonical, true);
});

