test("gap feed publishes and satisfies its closed healthy response schema", async (t) => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-gap-redaction-")), statusFile = path.join(root, "status.json"), store = new IndexStore("unused"); await store.load(); const original = parseBlock(JSON.parse(await fs.readFile(fixture, "utf8"))), replacement = { ...original, blockhash: "replacement-block", transactions: [], transfers: [], nativeTransfers: [], balanceChanges: [], swaps: [], poolLifecycleEvents: [] }; store.apply(original); store.apply(replacement); store.markFile("fixture.json", "a".repeat(64)); store.state.checkpoints.inbox.providerCredential = "must-not-escape"; store.state.reorgCorrections[0].lastError = "secret provider response"; assert.equal(store.recoveryQuality().canonical, true); await fs.writeFile(statusFile, JSON.stringify({ version: 2, source: "local-agave-rpc", genesisHash: MAINNET_GENESIS_HASH, commitment: "finalized", observedAt: new Date().toISOString(), cursor: replacement.slot, localValidatorTip: replacement.slot, lagSlots: 0, consecutiveFailures: 0, durableSkippedSlots: [] })); const server = createServer({ staleAfterMs: 120_000, exporterStatusFile: statusFile }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const response = await fetch(`http://127.0.0.1:${server.address().port}/internal/feed/gaps`), body = await response.json(), serialized = JSON.stringify(body), contract = queryContractSnapshot(), schema = contract.responseBodySchemas.gap_feed_success_v1, outcome = contract.http.find(({ path }) => path === "/internal/feed/gaps").responseOutcomes.find(({ status }) => status === 200); assert.equal(response.status, 200); assert.equal(outcome.representation.bodySchema, "gap_feed_success_v1"); assert.deepEqual(Object.keys(body).sort(), [...schema.required].sort()); assert.deepEqual(Object.keys(body.ingestion).sort(), [...schema.properties.ingestion.required].sort()); assert.deepEqual(Object.keys(body.checkpoint).sort(), schema.properties.checkpoint.required.slice().sort()); assert.deepEqual(Object.keys(body.reorgCorrections[0]).sort(), schema.properties.reorgCorrections.items.required.slice().sort()); assert.deepEqual(body.durableSkippedSlots, body.ingestion.durableSkippedSlots); assert.doesNotMatch(serialized, /must-not-escape|providerCredential|secret provider response|lastError/);
});

test("gap feed success schema rejects unsafe ingestion and cache projections", () => {
  const schema = queryContractSnapshot().responseBodySchemas.gap_feed_success_v1, ingestionSchema = schema.properties.ingestion, slotsRule = ingestionSchema.properties.durableSkippedSlots, valid = { schemaVersion: 1, available: true, reason: null, ingestion: { available: true, healthy: true, automationEligible: true, reason: null, version: 2, source: "local-agave-rpc", genesisHash: MAINNET_GENESIS_HASH, commitment: "finalized", observedAt: "2026-08-28T00:00:00.000Z", cursor: 98, localValidatorTip: 100, lagSlots: 2, maxLagSlots: 2, ageMs: 120_000, staleAfterMs: 120_000, consecutiveFailures: 0, durableSkippedSlots: [95, 97] }, durableSkippedSlots: [95, 97], reorgCorrections: [], checkpoint: null };
  const validate = (body) => { const ingestion = body.ingestion, slots = ingestion.durableSkippedSlots, difference = ingestionSchema.relationships.find(({ kind }) => kind === "difference"), mirror = schema.relationships.find(({ kind }) => kind === "mirror"); return ingestion.ageMs <= ingestion[ingestionSchema.properties.ageMs.maximumProperty] && ingestion.lagSlots <= ingestion[ingestionSchema.properties.lagSlots.maximumProperty] && ingestion.cursor <= ingestion[ingestionSchema.properties.cursor.maximumProperty] && ingestion[difference.result] === ingestion[difference.minuend] - ingestion[difference.subtrahend] && (!slotsRule.uniqueItems || new Set(slots).size === slots.length) && (!slotsRule.strictlyIncreasing || slots.every((slot, index) => index === 0 || slots[index - 1] < slot)) && mirror.properties.every((property) => JSON.stringify(body[property]) === JSON.stringify(body[mirror.target][property])); };
  assert.equal(validate(valid), true); for (const unsafe of [{ ...valid, ingestion: { ...valid.ingestion, ageMs: 120_001 } }, { ...valid, ingestion: { ...valid.ingestion, lagSlots: 3 } }, { ...valid, ingestion: { ...valid.ingestion, cursor: 99 } }, { ...valid, ingestion: { ...valid.ingestion, durableSkippedSlots: [97, 95] }, durableSkippedSlots: [97, 95] }, { ...valid, durableSkippedSlots: [95] }]) assert.equal(validate(unsafe), false);
});

test("ingestion and metrics fail closed for stale exporter status", async (t) => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "solana-stale-exporter-")), statusFile = path.join(root, "status.json"); await fs.writeFile(statusFile, JSON.stringify({ version: 2, source: "local-agave-rpc", commitment: "finalized", observedAt: "2020-01-01T00:00:00.000Z", lagSlots: 9, consecutiveFailures: 3 })); const store = new IndexStore("unused"); await store.load(); const server = createServer({ staleAfterMs: 120_000, exporterStatusFile: statusFile }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const base = `http://127.0.0.1:${server.address().port}`;
  const ingestion = await fetch(`${base}/api/v1/ingestion`); assert.equal(ingestion.status, 503); assert.equal((await ingestion.json()).reason, "exporter_failure"); const metrics = await (await fetch(`${base}/metrics`)).text(); assert.match(metrics, /terminal_dex_exporter_healthy 0/); assert.match(metrics, /terminal_dex_exporter_lag_slots 9/); assert.match(metrics, /terminal_dex_exporter_consecutive_failures 3/);
});

test("every direct operator CLI uses canonical file identity", async () => {
  const expected = ["account-snapshot.js", "amm-v4-pool-snapshot.js", "api-audit-retention.js", "archive-receipt.js", "backfill-qualification.js", "backup-preflight.js", "backup-status.js", "clmm-pool-snapshot.js", "cpmm-pool-snapshot.js", "dead-letter-reconcile.js", "exporter-health.js", "external-rpc.js", "geyser-abi-preflight.js", "inbox-archive.js", "inbox-retention.js", "local-validator-exporter.js", "local-validator-stream.js", "meteora-dlmm-pool-snapshot.js", "offchain-metadata-snapshot.js", "openbook-market-snapshot.js", "operational-job-worker.js", "orca-pool-snapshot.js", "phoenix-market-snapshot.js", "postgres-commercial-sync.js", "pump-bonding-curve-snapshot.js", "pump-swap-pool-snapshot.js", "recovery-qualification.js", "reduced-preflight.js", "usdc-oracle-snapshot.js", "warehouse-sync.js"];
  const sources = await Promise.all(expected.map(async (name) => [name, await fs.readFile(path.join(rootDir, "src", name), "utf8")]));
  for (const [name, source] of sources) {
    assert.match(source, /import \{ isInvokedFile \} from "\.\/invoked-file\.js";/, `${name} imports canonical identity`);
    assert.match(source, /isInvokedFile\([^\n]+fileURLToPath\(import\.meta\.url\)\)/, `${name} gates its main function canonically`);
    assert.doesNotMatch(source, /fileURLToPath\(import\.meta\.url\)\.toLowerCase\(\)\s*===|path\.resolve\(process\.argv\[1\]\)\s*===\s*fileURLToPath/, `${name} has no lexical entrypoint guard`);
  }
  const allSources = await Promise.all((await fs.readdir(path.join(rootDir, "src"))).filter((name) => name.endsWith(".js")).map((name) => fs.readFile(path.join(rootDir, "src", name), "utf8")));
  assert.equal(allSources.some((source) => /fileURLToPath\(import\.meta\.url\)\.toLowerCase\(\)\s*===|path\.resolve\(process\.argv\[1\]\)\s*===\s*fileURLToPath/.test(source)), false);
});

test("HTTP query contracts reject duplicate parameter ambiguity", async (t) => {
  const duplicateQueries = [
    "/internal/trending?limit=10&limit=20", "/internal/trending?window=1h&window=24h", "/internal/new-pairs?limit=10&limit=20", "/internal/candidates?limit=10&limit=20", "/internal/candidates?window=1h&window=24h",
    "/internal/pools/pool/quote?amountRaw=1&amountRaw=2", "/internal/pools/pool/quote?inputMint=a&inputMint=b", "/internal/pools/pool/quote?limitTick=1&limitTick=2", "/internal/tokens/mint/trades?limit=10&limit=20", "/internal/tokens/mint/ohlcv?interval=60&interval=300",
    "/internal/tokens/mint/executable-depth?side=buy&side=sell", "/internal/tokens/mint/executable-depth?amountRaw=1&amountRaw=2", "/internal/wallets/wallet/funding?limit=10&limit=20", "/api/v1/blocks?cursor=a&cursor=b", "/api/v1/transactions?limit=10&limit=20",
    "/api/v1/swaps?mint=a&mint=b", "/api/v1/swaps?protocol=a&protocol=b", "/api/v1/tokens?cursor=a&cursor=b", "/api/v1/pools?status=active&status=migrated", "/api/v1/candles/pool?interval=60&interval=300"
  ];
  for (const requestTarget of duplicateQueries) assert.throws(() => validateUniqueQueryParameters(new URL(requestTarget, "http://localhost")), (error) => error.code === "BAD_REQUEST" && error.message === "query parameters must appear at most once", requestTarget);
  assert.doesNotThrow(() => validateUniqueQueryParameters(new URL("/api/v1/swaps?mint=a&pool=b&protocol=c&limit=10", "http://localhost")));
  const store = new IndexStore("unused"); await store.load(); const server = createServer({}, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const response = await fetch(`http://127.0.0.1:${server.address().port}/api/v1/blocks?limit=1&limit=2`); assert.equal(response.status, 400); assert.deepEqual(await response.json(), { error: "bad_request", detail: "query parameters must appear at most once" });
});

