  const cpmmRaw = { ...orcaRaw, job_key: "cpmm-pool-snapshot:11111111111111111111111111111111", job_type: "cpmm_pool_snapshot" }; assert.deepEqual(validateOperationalJob(cpmmRaw), { id: 7, attempts: 2, type: "cpmm_pool_snapshot", target: cpmmRaw.payload.pool });
  const ammV4Raw = { ...orcaRaw, job_key: "amm-v4-pool-snapshot:11111111111111111111111111111111", job_type: "amm_v4_pool_snapshot" }; assert.deepEqual(validateOperationalJob(ammV4Raw), { id: 7, attempts: 2, type: "amm_v4_pool_snapshot", target: ammV4Raw.payload.pool }); assert.doesNotThrow(() => validateOperationalJob({ ...ammV4Raw, payload: { ...ammV4Raw.payload, reason: "incomplete_state_evidence", sourceSlot: 42 } })); assert.throws(() => validateOperationalJob({ ...ammV4Raw, payload: { ...ammV4Raw.payload, reason: "incomplete_quote_evidence" } }), /scheduling evidence/);
  const pumpSwapRaw = { ...orcaRaw, job_key: "pump-swap-pool-snapshot:11111111111111111111111111111111", job_type: "pump_swap_pool_snapshot" }; assert.deepEqual(validateOperationalJob(pumpSwapRaw), { id: 7, attempts: 2, type: "pump_swap_pool_snapshot", target: pumpSwapRaw.payload.pool });
  const pumpCurveRaw = { ...raw, job_key: "pump-bonding-curve-snapshot:11111111111111111111111111111111", job_type: "pump_bonding_curve_snapshot" }; assert.deepEqual(validateOperationalJob(pumpCurveRaw), { id: 7, attempts: 2, type: "pump_bonding_curve_snapshot", target: pumpCurveRaw.payload.mint });
  const metadataRaw = { ...raw, job_key: "offchain-metadata-snapshot:11111111111111111111111111111111", job_type: "offchain_metadata_snapshot", payload: { schemaVersion: 1, chain: "solana-mainnet", mint: "11111111111111111111111111111111", onchainMetadataHash: "a".repeat(64), uri: "https://metadata.example/token.json", ...scheduling } }; assert.deepEqual(validateOperationalJob(metadataRaw), { id: 7, attempts: 2, type: "offchain_metadata_snapshot", target: metadataRaw.payload.mint, onchainMetadataHash: metadataRaw.payload.onchainMetadataHash, uri: metadataRaw.payload.uri }); assert.throws(() => validateOperationalJob({ ...metadataRaw, payload: { ...metadataRaw.payload, uri: "http://metadata.example/token.json" } }), /metadata job evidence/); assert.throws(() => validateOperationalJob({ ...metadataRaw, payload: { ...metadataRaw.payload, onchainMetadataHash: "bad" } }), /metadata job evidence/);
