  await fs.writeFile(path.join(root, "indexer-state.tar"), Buffer.concat([entry("data/./index.json", "{}"), entry("data/exporter-status.json", "{}"), Buffer.alloc(1_024)])); await createBackupManifest(root, { backupId: "20260822T000000Z", createdAt: "2026-08-22T00:00:00.000Z", writersQuiesced: true }); await writeSums(); await assert.rejects(preflightBackup(root, { now: Date.parse("2026-08-22T01:00:00.000Z") }), /unsafe/); await fs.writeFile(path.join(root, "indexer-state.tar"), tar); await createBackupManifest(root, { backupId: "20260822T000000Z", createdAt: "2026-08-22T00:00:00.000Z", writersQuiesced: true }); await writeSums();
