  assert.throws(() => buildCommercialSyncSql(registry, JSON.stringify({ schemaVersion: 1, observedAt: "2026-08-22T01:00:00.000Z", tenantId: "tenant-a", path: "/rpc", statusCode: "200", durationMs: 1 })), /invalid tenant usage audit/);
