test("warehouse sync failures immediately override the last successful checkpoint without diagnostic identities", async (t) => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "warehouse-failure-status-")); t.after(() => fs.rm(root, { recursive: true, force: true })); const filename = path.join(root, "status.json"), checkpointUpdatedAt = "2026-08-24T00:00:00.000Z", observedAt = "2026-08-24T00:00:01.000Z", healthy = { available: true, healthy: true, reason: null, updatedAt: checkpointUpdatedAt, reconciliation: { verified: true } };
  const status = await writeWarehouseFailureStatus(filename, checkpointUpdatedAt, { stage: "reconciliation", invalidPostgresPreimages: { tokens: 2, pools: 0, candidates: 1, identity: "must-not-persist" }, observedAt }); assert.deepEqual(JSON.parse(await fs.readFile(filename, "utf8")), status); assert.equal(/mint|address|contentHash|identity/.test(JSON.stringify(status)), false); assert.deepEqual(applyWarehouseFailureStatus(healthy, status), { ...healthy, healthy: false, reason: "warehouse_sync_failed", lastFailureAt: observedAt, failure: { stage: "reconciliation", invalidPostgresPreimages: { tokens: 2, pools: 0, candidates: 1 } } }); assert.equal(applyWarehouseFailureStatus(healthy, null), healthy); for (const invalid of [{ evidenceReadError: "invalid_json" }, { ...status, observedAt: checkpointUpdatedAt }, { ...status, observedAt: "2026-08-24T00:00:01Z" }, { ...status, chain: "solana" }, { ...status, stage: "unknown" }, { ...status, invalidPostgresPreimages: { tokens: -1, pools: 0, candidates: 0 } }]) assert.deepEqual(applyWarehouseFailureStatus(healthy, invalid), { ...healthy, healthy: false, reason: "warehouse_status_invalid" }); assert.deepEqual(applyWarehouseFailureStatus({ ...healthy, updatedAt: observedAt }, status), { ...healthy, updatedAt: observedAt }); await assert.rejects(writeWarehouseFailureStatus(filename, observedAt, { stage: "reconciliation", observedAt: checkpointUpdatedAt }), /invalid warehouse failure status/); await assert.rejects(writeWarehouseFailureStatus(filename, checkpointUpdatedAt, { stage: "reconciliation", observedAt: "2026-08-24T00:00:01Z" }), /invalid warehouse failure status/);
});

