test("WebSocket isolates replayable snapshot updates from block subscriptions", async (t) => {
  const store = new IndexStore("unused"); await store.load(); store.applyAccountSnapshot({ schemaVersion: 1, chain: "solana", genesisHash: MAINNET_GENESIS_HASH, commitment: "finalized", slot: 700, observedAt: new Date().toISOString(), mints: [{ mint: "snapshot-mint", mintProgramId: SPL_TOKEN_PROGRAM, mintInfo: { supply: "0", decimals: 6 }, accounts: [] }] }); const server = createServer({ webSocketHeartbeatMs: 60_000 }, store); await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve)); t.after(() => new Promise((resolve) => server.close(resolve))); const base = `ws://127.0.0.1:${server.address().port}/ws?cursor=0`;
  const collect = async (url, expected) => { const socket = new WebSocket(url), messages = []; socket.onmessage = ({ data }) => messages.push(JSON.parse(data)); await new Promise((resolve, reject) => { socket.onopen = resolve; socket.onerror = reject; }); while (messages.length < expected) await new Promise((resolve) => setTimeout(resolve, 5)); return { socket, messages }; };
  const snapshots = await collect(`${base}&mint=snapshot-mint&topic=snapshots`, 2); assert.equal(snapshots.messages[1].type, "account_snapshot_applied"); assert.deepEqual(snapshots.messages[1].mints.map((row) => row.mint), ["snapshot-mint"]); snapshots.socket.close(); const blocks = await collect(`${base}&topic=blocks`, 1); await new Promise((resolve) => setTimeout(resolve, 20)); assert.equal(blocks.messages.length, 1); blocks.socket.close();
});

