  assert.deepEqual(messages[0].acknowledgement, { schemaVersion: 1, type: "ack", cumulative: true, timeoutMs: 2_000, maximumOutstanding: 1_024 }); socket.send(JSON.stringify({ schemaVersion: 1, type: "ack", sequence: 1 }));
  let metrics; for (let attempt = 0; attempt < 20; attempt++) { metrics = await (await fetch(`${base}/metrics`)).text(); if (/terminal_dex_websocket_acknowledgement_latency_seconds_count 1/.test(metrics)) break; await new Promise((resolve) => setTimeout(resolve, 5)); }
  assert.match(metrics, /terminal_dex_websocket_acknowledgement_clients 1/); assert.match(metrics, /terminal_dex_websocket_acknowledgement_latency_seconds_count 1/); assert.match(metrics, /terminal_dex_websocket_acknowledgement_latency_seconds_bucket\{le="2"\} 1/); const bucket = (body, le) => Number(body.match(new RegExp(`terminal_dex_websocket_acknowledgement_latency_seconds_bucket\\{le="${le}"\\} (\\d+)`))[1]), fastBefore = bucket(metrics, "0.1"), halfSecondBefore = bucket(metrics, "0.5");
  const block = parseBlock(JSON.parse(await fs.readFile(fixture, "utf8"))); store.apply({ ...block, slot: 101, blockhash: "block-101", previousBlockhash: "block-100", parentSlot: 100, transactions: [], transfers: [] }); await store.save(); while (messages.length < 3) await new Promise((resolve) => setTimeout(resolve, 5)); socket.send(JSON.stringify({ schemaVersion: 1, type: "ack", sequence: 2 }));
  for (let attempt = 0; attempt < 20; attempt++) { metrics = await (await fetch(`${base}/metrics`)).text(); if (/terminal_dex_websocket_acknowledgement_latency_seconds_count 2/.test(metrics)) break; await new Promise((resolve) => setTimeout(resolve, 5)); } assert.equal(bucket(metrics, "0.1"), fastBefore); assert.equal(bucket(metrics, "0.5"), halfSecondBefore + 1);
